import { createMatchServer } from './apps/server/src/match-server';
import { prepareGoldenEaterRoom, goldenEaterHostClientId, goldenEaterSourceInstanceId } from './e2e/support/prepare-golden-eater-room';
import { WebSocket } from 'ws';
async function connect(port:number,id:string,token:string){const ws=new WebSocket('ws://127.0.0.1:'+port+'/rooms/'+id+'?clientId='+goldenEaterHostClientId+'&reconnectToken='+encodeURIComponent(token));const frames:any[]=[];ws.on('message',b=>frames.push(JSON.parse(b.toString())));await new Promise<void>((r,j)=>{ws.once('open',()=>r());ws.once('error',j)});return {ws,frames}}
async function close(ws:WebSocket){const p=new Promise(r=>ws.once('close',r));ws.close();await p}
(async()=>{
 const server=createMatchServer();const port=await server.listen(0);const id='rb-auth';server.hub.createRoom({roomId:id,hostClientId:goldenEaterHostClientId});const room=server.hub.getRoom(id);prepareGoldenEaterRoom(room);
 server.hub.joinRoom(id,{clientId:'guest',displayName:'Guest',role:'spectator'});const guest=server.hub.project(id,'guest');const leaked=guest.clients.find(c=>c.id===goldenEaterHostClientId)?.reconnectToken;
 const before=room.session!.state.abilityRuntime!.revision;const {ws,frames}=await connect(port,id,leaked??'');
 ws.send(JSON.stringify({type:'client:dispatch_command',expectedRevision:before,command:{type:'activate_ability',cardInstanceId:goldenEaterSourceInstanceId,abilityId:'sc-kintoki-3.golden-eater'}}));
 await new Promise(r=>setTimeout(r,200));
 console.log(JSON.stringify({case:'guest_projection_host_impersonation',guestIsHost:guest.viewer.isHost,hostTokenExposed:typeof leaked==='string',acceptedSocket:ws.readyState===WebSocket.OPEN,revisionBefore:before,revisionAfter:room.session!.state.abilityRuntime!.revision,pendingController:room.session!.state.abilityRuntime!.pendingDecision?.controllerId,errors:frames.filter(x=>x.type==='server:error')}));
 await close(ws);await server.close();
 const s=createMatchServer();const p=await s.listen(0);const id2='rb-revision';const proj=s.hub.createRoom({roomId:id2,hostClientId:goldenEaterHostClientId});const r=s.hub.getRoom(id2);prepareGoldenEaterRoom(r);const token=proj.clients.find(c=>c.id===goldenEaterHostClientId)!.reconnectToken;const c=await connect(p,id2,token);
 const snapshot=()=>({revision:r.session!.state.abilityRuntime!.revision,phase:r.session!.state.round.activePhase,priority:r.session!.state.round.prioritySeat,logs:r.session!.logs.length,version:s.hub.version(id2)});
 const b=snapshot();c.ws.send(JSON.stringify({type:'client:end_turn'}));await new Promise(r=>setTimeout(r,200));
 console.log(JSON.stringify({case:'raw_ws_end_turn_missing_revision',before:b,after:snapshot(),errors:c.frames.filter(x=>x.type==='server:error')}));
 await close(c.ws);await s.close();
})().catch(e=>{console.error(e);process.exitCode=1});

import { createMatchServer } from './apps/server/src/match-server';
import { goldenEaterHostClientId,prepareGoldenEaterRoom } from './e2e/support/prepare-golden-eater-room';
(async()=>{const s=createMatchServer();const port=await s.listen(0);const id='rb-token-boundary';s.hub.createRoom({roomId:id,hostClientId:goldenEaterHostClientId});const room=s.hub.getRoom(id);prepareGoldenEaterRoom(room);
const input=id+':'+goldenEaterHostClientId;let hash=2166136261;for(const ch of input){hash^=ch.charCodeAt(0);hash=Math.imul(hash,16777619)}const guessed='reconnect-'+(hash>>>0).toString(36);
const expected=room.clients.find(c=>c.id===goldenEaterHostClientId)!.reconnectToken;
const version=s.hub.version(id);const response=await fetch('http://127.0.0.1:'+port+'/rooms/'+id+'/join',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({clientId:goldenEaterHostClientId,displayName:'Impersonated host'})});const body:any=await response.json();
console.log(JSON.stringify({case:'credential_generation_and_duplicate_join',tokenGuessMatches:guessed===expected,httpStatus:response.status,returnedHostCredential:body.reconnectToken===expected,returnedViewerIsHost:body.projection?.viewer?.isHost,versionBefore:version,versionAfter:s.hub.version(id),hostNameChanged:room.clients.find(c=>c.id===goldenEaterHostClientId)?.displayName==='Impersonated host'}));await s.close()})().catch(e=>{console.error(e);process.exitCode=1});
